<?php require_once 'config/db.php'; require_once 'includes/auth.php'; require_role(['customer']); $u=$_SESSION['user']; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $ids=$_POST['qty']??[];$items=[];$subtotal=0;$tax=0;foreach($ids as $pid=>$qty){$qty=(int)$qty;if($qty<=0)continue;$pid=(int)$pid;$p=$conn->query("SELECT * FROM products WHERE id=$pid")->fetch_assoc();if(!$p||$qty>$p['stock']){$err='Quantity exceeds available stock.';break;}$line=$p['price']*$qty;$items[]=['p'=>$p,'q'=>$qty,'line'=>$line];$subtotal+=$line;$tax+=$line*$p['tax_rate']/100;}if(!$err&&!$items)$err='Select at least one product.';if(!$err){$total=$subtotal+$tax;$addr=trim($_POST['address']?:$u['address']);$s=$conn->prepare('INSERT INTO orders(customer_id,subtotal,tax,total,shipping_address) VALUES(?,?,?,?,?)');$s->bind_param('iddds',$u['id'],$subtotal,$tax,$total,$addr);$s->execute();$oid=$conn->insert_id;foreach($items as $it){$p=$it['p'];$s=$conn->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price,tax_rate) VALUES(?,?,?,?,?)');$s->bind_param('iiidd',$oid,$p['id'],$it['q'],$p['price'],$p['tax_rate']);$s->execute();}$method=$_POST['method'];$s=$conn->prepare('INSERT INTO payments(order_id,method,amount,status) VALUES(?,?,? ,"Paid")');$s->bind_param('isd',$oid,$method,$total);$s->execute();foreach($items as $it){$pid=$it['p']['id'];$q=$it['q'];$conn->query("UPDATE products SET stock=stock-$q WHERE id=$pid");}header('Location:orders.php?msg=Order+placed+and+payment+recorded');exit;}}
$ps=$conn->query('SELECT * FROM products WHERE stock>0 ORDER BY name');include 'includes/header.php';?><div class="card"><h2>Place Order</h2><?php if($err):?><div class="error"><?=h($err)?></div><?php endif;?><form method="post"><table><tr><th>Product</th><th>Price</th><th>Stock</th><th>Quantity</th></tr><?php while($p=$ps->fetch_assoc()):?><tr><td><?=h($p['name'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><input type="number" min="0" max="<?=$p['stock']?>" value="0" name="qty[<?=$p['id']?>]"></td></tr><?php endwhile;?></table><label>Shipping Address</label><input name="address" value="<?=h($u['address'])?>" required><label>Payment Method</label><select name="method"><option>Cash</option><option>Check</option><option>Credit</option></select><button class="btn success">Place Order</button></form></div><?php include 'includes/footer.php'; ?>
